,\n    \"@deepseek-ai/dsh-client-ui-slots\": \"^0.1.0-rc.6 || ^0.2.0-0 || ^0.2.1-0\",\n    \"@deepseek-ai/dsh-credentials\": \"^0.1.0-rc.6 || ^0.2.0-0 || ^0.2.1-0\",\n    \"@deepseek-ai/dsh-llm\": \"^0.1.0-rc.6 || ^0.2.0-0 || ^0.2.1-0\",\n    \"@deepseek-ai/dsh-settings\": \"^0.1.0-rc.6 || ^0.2.0-0 || ^0.2.1-0\",\n    \"@deepseek-ai/dsh-web\": \"^0.1.0-rc.6 || ^0.2.0-0 || ^0.2.1-0\",\n    \"@deepseek-ai/schemastery\": \"^3.18.1\",\n    \"react\": \"^18.2.0\"\n  },\n  \"scripts\": {\n    \"build\": \"node -e \\\"require('fs').rmSync('lib',{recursive:true,force:true})\\\" && tsc -p tsconfig.build.json && tsdown\",\n    \"prepack\": \"npm run build\",\n    \"bundle\": \"tsdown\",\n    \"test\": \"node --experimental-strip-types --test test/*.test.ts test/*.test.mjs test/*.smoke.mjs src/host/logic.test.ts\",\n    \"smoke\": \"node --experimental-strip-types --test test/*.test.ts test/*.test.mjs test/*.smoke.mjs src/host/logic.test.ts\",\n    \"typecheck\": \"tsc -p tsconfig.json --noEmit && tsc -p tsconfig.client.json --noEmit\"\n  },\n  \"devDependencies\": {\n    \"@types/node\": \"^22.10.0\",\n    \"@types/react\": \"~18.3.31\",\n    \"@types/ws\": \"^8.5.14\",\n    \"semver\": \"^7.8.5\",\n    \"tsdown\": \"^0.22.14\",\n    \"typescript\": \"^5.9.3\"\n  }\n}\n"
